  if(roll<0.35){
    var k=pick(kw,rnd); topic=k;
    group='components'; title=k+' subsystem - boundless '+KIND+' record';
    definition='Boundless elaboration of the '+k+' subsystem within '+BRIEF.name+'.';
    src='Public knowledge - future technology reference'; ladder=2;
  }else if(roll<0.60){
    var yr=2027+((rnd()*80)|0); topic='forecast-'+yr;
    group='forecasts'; title=yr+' - boundless '+BRIEF.name+' forecast';
    definition='A generated forecast milestone for '+BRIEF.name+' in '+yr+', extrapolated from the archive trajectory.';
    src='Forecast - planning scenario'; ladder=2;
  }else if(roll<0.80){
    topic='drill-'+seed;
    group='practice'; title='Boundless drill '+seed+' - '+BRIEF.name+' practice';
    definition='A generated drill exercising '+BRIEF.name+' on seed-derived data.';
    src='Signature concept - practice'; ladder=1+((rnd()*3)|0);
  }else{
    topic='demo-'+seed;
    group='demos'; title='Boundless demo '+seed+' - '+BRIEF.name+' systems';
    definition='A generated systems demonstration for '+BRIEF.name+'.';
    src='Signature concept - demonstration'; ladder=2;
  }
  var desc=topic+': '+definition+' Seed '+seed+' reproduces this record exactly - deterministic generation means the same seed always yields this same record.';
